<script setup lang="ts">
const route = useRoute();
const { t } = useI18n();
const { buildWhatsAppUrl } = useWhatsApp();
const {
  isValidSlug: isValidArtisanSlug,
  getProduct: getArtisanProduct,
} = useArtisanProducts();
const { isValidSlug: isValidRawSlug, getProduct: getRawProduct } =
  useRawProducts();

const productName = computed(() => {
  const slug = route.params.slug;

  if (typeof slug !== "string") {
    return null;
  }

  if (
    route.path.startsWith("/product/artisan-products/") &&
    isValidArtisanSlug(slug)
  ) {
    return getArtisanProduct(slug).name;
  }

  if (
    route.path.startsWith("/product/spices-commodities/") &&
    isValidRawSlug(slug)
  ) {
    return getRawProduct(slug).name;
  }

  return null;
});

const message = computed(() =>
  productName.value
    ? t("whatsapp.productMessage", { productName: productName.value })
    : t("whatsapp.generalMessage"),
);

const whatsappUrl = computed(() => buildWhatsAppUrl(message.value));
const tooltip = computed(() => t("whatsapp.tooltip"));
</script>

